fn word_lengths(text: &str) -> Vec<(String, usize)> {
    text.split_whitespace()
        .map(|w| {
            let clean: String = w.chars()
                .filter(|c| c.is_alphanumeric())
                .collect();
            let len = clean.len();
            (clean, len)
        })
        .filter(|(w, _)| !w.is_empty())
        .collect()
}

fn main() {
    let pairs = word_lengths("Hello, world! Rust is great.");
    for (word, len) in &pairs {
        println!("{word}: {len}");
    }
}

use std::collections::HashMap;

fn word_freq(text: &str) -> HashMap<String, usize> {
    let mut freq = HashMap::new();
    for word in text.split_whitespace() {
        let key = word.to_lowercase();
        *freq.entry(key).or_insert(0) += 1;
    }
    freq
}

fn main() {
    let counts = word_freq("the cat sat on the mat");
    for (word, count) in &counts {
        println!("{word}: {count}");
    }
}

