use std::num::ParseIntError;

#[derive(Debug)]
enum AppError {
    Parse(ParseIntError),
    OutOfRange(i32),
    Empty,
}

fn parse_port(input: &str) -> Result<u16, AppError> {
    let trimmed = input.trim();
    if trimmed.is_empty() {
        return Err(AppError::Empty);
    }
    let n: i32 = trimmed.parse().map_err(AppError::Parse)?;
    match n {
        1..=65535 => Ok(n as u16),
        _ => Err(AppError::OutOfRange(n)),
    }
}

fn main() {
    for input in ["8080", "", "abc", "99999"] {
        match parse_port(input) {
            Ok(port) => println!("port: {port}"),
            Err(AppError::Empty) => println!("empty input"),
            Err(AppError::Parse(e)) => println!("parse error: {e}"),
            Err(AppError::OutOfRange(n)) => println!("out of range: {n}"),
        }
    }
}

struct Excerpt<'a> {
    text: &'a str,
    start: usize,
    end: usize,
}

impl<'a> Excerpt<'a> {
    fn new(text: &'a str, start: usize, end: usize) -> Self {
        let end = end.min(text.len());
        let start = start.min(end);
        Self { text, start, end }
    }

    fn content(&self) -> &str {
        &self.text[self.start..self.end]
    }

    fn is_empty(&self) -> bool {
        self.start == self.end
    }

    fn overlaps(&self, other: &Excerpt<'_>) -> bool {
        std::ptr::eq(self.text, other.text)
            && self.start < other.end
            && other.start < self.end
    }
}

fn apply_pipeline<T, F>(items: Vec<T>, stages: &[F]) -> Vec<T>
where
    T: Clone,
    F: Fn(&T) -> bool,
{
    let mut result = items;
    for stage in stages {
        result = result
            .into_iter()
            .filter(|item| stage(item))
            .collect();
    }
    result
}

fn main() {
    let numbers: Vec<i32> = (1..=50).collect();
    let threshold = 10;
    let stages: Vec<Box<dyn Fn(&i32) -> bool>> = vec![
        Box::new(|n| n % 2 == 0),
        Box::new(move |n| *n > threshold),
        Box::new(|n| *n < 40),
    ];
    let result = apply_pipeline(numbers, &stages);
    println!("{result:?}");
}

use std::fmt;
use std::str::FromStr;

fn parse_list<T>(input: &str, sep: char) -> Result<Vec<T>, String>
where
    T: FromStr + fmt::Debug,
    T::Err: fmt::Display,
{
    let mut results = Vec::new();
    for (i, part) in input.split(sep).enumerate() {
        let trimmed = part.trim();
        if trimmed.is_empty() {
            continue;
        }
        match trimmed.parse::<T>() {
            Ok(val) => results.push(val),
            Err(e) => {
                return Err(format!(
                    "field {i}: cannot parse '{trimmed}': {e}"
                ));
            }
        }
    }
    Ok(results)
}

fn main() {
    let ints: Result<Vec<i32>, _> = parse_list("1, 2, 3, 4", ',');
    let floats: Result<Vec<f64>, _> = parse_list("1.5; 2.7; 3.9", ';');
    println!("{ints:?}");
    println!("{floats:?}");
}

