fn make_adder(base: i32) -> impl Fn(i32) -> i32 {
    move |x| base + x
}

fn make_chain(
    f: impl Fn(i32) -> i32,
    g: impl Fn(i32) -> i32,
) -> impl Fn(i32) -> i32 {
    move |x| g(f(x))
}

fn apply_n(
    f: &dyn Fn(i32) -> i32,
    mut val: i32,
    n: usize,
) -> i32 {
    for _ in 0..n {
        val = f(val);
    }
    val
}

fn main() {
    let add5 = make_adder(5);
    let double_add5 = make_chain(add5, |x| x * 2);
    let result = apply_n(&double_add5, 1, 3);
    println!("{result}");
}

#[derive(Debug, Clone)]
enum Value {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Array(Vec<Value>),
    Object(Vec<(String, Value)>),
}

impl Value {
    fn get(&self, path: &[&str]) -> Option<&Value> {
        match (self, path.split_first()) {
            (_, None) => Some(self),
            (Value::Object(entries), Some((key, rest))) => {
                for (k, v) in entries {
                    if k == key {
                        return v.get(rest);
                    }
                }
                None
            }
            (Value::Array(items), Some((idx_str, rest))) => {
                if let Ok(idx) = idx_str.parse::<usize>() {
                    if let Some(item) = items.get(idx) {
                        return item.get(rest);
                    }
                }
                None
            }
            _ => None,
        }
    }

    fn is_truthy(&self) -> bool {
        match self {
            Value::Null => false,
            Value::Bool(b) => *b,
            Value::Num(n) => *n != 0.0,
            Value::Str(s) => !s.is_empty(),
            Value::Array(a) => !a.is_empty(),
            Value::Object(o) => !o.is_empty(),
        }
    }
}

struct Machine<S> {
    state: S,
}

struct Idle;
struct Running {
    task: String,
}
struct Finished {
    result: String,
}

impl Machine<Idle> {
    fn new() -> Self {
        Machine { state: Idle }
    }

    fn start(self, task: &str) -> Machine<Running> {
        Machine {
            state: Running {
                task: task.to_string(),
            },
        }
    }
}

impl Machine<Running> {
    fn complete(self) -> Machine<Finished> {
        let result = format!("done: {}", self.state.task);
        Machine {
            state: Finished { result },
        }
    }

    fn cancel(self) -> Machine<Idle> {
        Machine { state: Idle }
    }
}

impl Machine<Finished> {
    fn result(&self) -> &str {
        &self.state.result
    }

    fn reset(self) -> Machine<Idle> {
        Machine { state: Idle }
    }
}

fn main() {
    let m = Machine::new();
    let m = m.start("compile");
    let m = m.complete();
    println!("{}", m.result());
    let _m = m.reset();
}

use std::collections::HashMap;
use std::fmt;

#[derive(Debug)]
enum LookupError {
    SectionMissing(String),
    KeyMissing { section: String, key: String },
    ParseFailed { key: String, raw: String },
}

impl fmt::Display for LookupError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            LookupError::SectionMissing(s) => {
                write!(f, "section not found: {s}")
            }
            LookupError::KeyMissing { section, key } => {
                write!(f, "key '{key}' not in [{section}]")
            }
            LookupError::ParseFailed { key, raw } => {
                write!(f, "cannot parse '{raw}' for key '{key}'")
            }
        }
    }
}

type Config = HashMap<String, HashMap<String, String>>;

fn get_typed<T: std::str::FromStr>(
    config: &Config,
    section: &str,
    key: &str,
) -> Result<T, LookupError> {
    let sec = config
        .get(section)
        .ok_or_else(|| LookupError::SectionMissing(section.to_string()))?;
    let raw = sec.get(key).ok_or_else(|| LookupError::KeyMissing {
        section: section.to_string(),
        key: key.to_string(),
    })?;
    raw.parse::<T>().map_err(|_| LookupError::ParseFailed {
        key: key.to_string(),
        raw: raw.clone(),
    })
}
